/*
 * Example: query a remote GDX file from DuckDB-WASM.
 *
 * This script is intended to be bundled (Vite, Webpack, etc.) for the browser
 * or run inside an ESM-friendly runtime such as Node 18+ with an import
 * loader. It relies on the "duckdb-wasm" npm package and the gdx
 * extension generated by this repository.
 */

import {
  AsyncDuckDB,
  ConsoleLogger,
  DuckDBDataProtocol,
  createWorker,
  getJsDelivrBundles,
  selectBundle
} from '@duckdb/duckdb-wasm';

// Hosted copy of the sample transport.gdx file used throughout the project.
// Update this URL when mirroring the dataset elsewhere.
const REMOTE_GDX_URL = 'https://raw.githubusercontent.com/duckdb/duckdb-gdx/main/test/data/gdx/transport.gdx';

async function main() {
  const logger = new ConsoleLogger();
  const bundles = getJsDelivrBundles();
  const bundle = await selectBundle(bundles);
  const worker = await createWorker(bundle.mainWorker);
  const db = new AsyncDuckDB(logger, worker);

  try {
    await db.instantiate(bundle.mainModule, bundle.pthreadWorker ?? undefined);

    const connection = await db.connect();

    try {
      // Ensure remote access helpers are available. Using explicit SQL keeps the
      // example compatible with duckdb-wasm versions that do not expose
      // installExtension/loadExtension helpers.
      await connection.query(`
        INSTALL gdx;
        LOAD gdx;
      `);

      // Optionally register a logical name for the remote file. The HTTP data
      // protocol signals to DuckDB that range requests should be used when the
      // gdx WASM adapter pulls data through the default HTTP module.
      await connection.useUnsafe(async (bindings) => {
        await bindings.registerFileURL(
          'transport.gdx',
          REMOTE_GDX_URL,
          DuckDBDataProtocol.HTTP,
          /* directIO */ true
        );
      });

      const result = await connection.query(`
        SELECT
          i AS origin,
          j AS destination,
          value
        FROM read_gdx('transport.gdx', 'd', dimension_filters => map(['i'], ['seattle']))
        ORDER BY destination
        LIMIT 5;
      `);

      const rows = result
        .toArray()
        .map((row) => row.toJSON?.() ?? Object.fromEntries(row.entries?.() ?? []));
      console.table(rows);
    } finally {
      await connection.close();
    }
  } finally {
    await db.terminate();
    worker.terminate();
  }
}

main().catch((error) => {
  console.error('DuckDB-WASM demo failed:', error);
});
